const returnItems = [];

for (const item of $input.all()) {
  const body = item.json.body || {};
  const data = body.data || {};

  if (body.event !== "messages.upsert") continue;

  // ANTI-DUPLICAÇÃO INTELIGENTE
  if (data.status) {
      if (["DELIVERY_ACK", "READ", "PLAYED"].includes(data.status)) {
         if (data.key?.fromMe === true) continue;
      }
  }

  if (!data.message) continue;

  let remoteJid = data.key?.remoteJid || "";
  let phoneNumber = remoteJid.split('@')[0]; 

  if (remoteJid.includes('@lid')) {
    remoteJid = `${phoneNumber}@s.whatsapp.net`;
  }

  const msg = data.message?.ephemeralMessage?.message || data.message;

  let messageText = "";
  let isAudio = false;
  let isImage = false;
  let imageBase64 = "";

  // CAÇADOR DE TEXTOS, ÁUDIOS E IMAGENS
  if (msg?.conversation) {
    messageText = msg.conversation;
  } else if (msg?.extendedTextMessage?.text) {
    messageText = msg.extendedTextMessage.text;
  } else if (msg?.audioMessage) {
    isAudio = true;
  } else if (msg?.reactionMessage?.text) {
    messageText = `[O paciente reagiu à sua mensagem com o emoji: ${msg.reactionMessage.text}]`;
  } else if (msg?.imageMessage) {
    // 👁️ DETECTOR DE IMAGEM ADICIONADO
    isImage = true;
    messageText = msg.imageMessage.caption || ""; // Pega o texto que o paciente digitou junto com a foto
    imageBase64 = data.message.base64 || data.base64 || ""; // Captura a imagem em base64 da Evolution
  } else if (msg?.documentMessage) {
      // Bônus: Caso mandem a receita em PDF
      messageText = `[O paciente enviou um arquivo PDF/Documento chamado: ${msg.documentMessage.title}]`;
  }

  // Se não tem texto, nem áudio, nem imagem, aborta
  if (!messageText && !isAudio && !isImage) continue; 

  const fromMe = data.key?.fromMe === true;
  const isSilvia = messageText.includes('\u200D'); 

  let tipoRota = "paciente";

  if (fromMe) {
      if (isSilvia) {
          continue;
      } else if (messageText === '/retomar') {
          tipoRota = "retomar"; 
      } else {
          tipoRota = "pausar"; 
      }
  }

  returnItems.push({
    json: {
      sessionId: phoneNumber,             
      remoteJid: remoteJid,               
      senderNumber: phoneNumber,         
      pushName: data.pushName || "Paciente",                 
      text: messageText,                  
      isAudio: isAudio,
      isImage: isImage, // <--- Nova tag
      imageBase64: imageBase64, // <--- Dados da imagem
      evoKey: data.key,
      evoMessage: data.message,
      fromMe: fromMe,
      tipoRota: tipoRota 
    }
  });
}

return returnItems;

