// Pega todos os dados originais lá do começo (WhatsApp, JID, Nome, etc)
const originalData = $('Code').first().json;

// Caçador robusto da resposta do Gemini
let geminiAnalysis = "Imagem analisada, mas sem texto detectado.";

if ($json.content && $json.content.parts && $json.content.parts.length > 0) {
    geminiAnalysis = $json.content.parts[0].text;
} else if ($json.text) {
    geminiAnalysis = $json.text;
} else if ($json.output) {
    geminiAnalysis = $json.output;
}

// Montamos o "pensamento interno" da Silvia
let novoTexto = `[SISTEMA (LEITURA VISUAL): O paciente enviou uma imagem. Dados extraídos:]\n${geminiAnalysis}`;

// Se o paciente digitou alguma legenda junto com a foto, adicionamos ao contexto
if (originalData.text && originalData.text !== "") {
    novoTexto += `\n\n[Mensagem digitada pelo paciente junto com a imagem:]\n"${originalData.text}"`;
}

// Retornamos o item completo pro n8n colocar na Fila de 12 Segundos
return {
    json: {
        ...originalData, 
        text: novoTexto  
    }
};

// Verifica se há base64 vindo do JSON (como text/string)
const base64Str = $json.imageBase64;

if (!base64Str) {
  // Se por algum motivo a imagem veio vazia, repassa o item
  return [{ json: $json }];
}

// O base64 da Evolution às vezes vem com prefixo (ex: "data:image/jpeg;base64,..."). 
// Precisamos limpar isso para o Buffer não quebrar.
const base64Data = base64Str.replace(/^data:image\/\w+;base64,/, "");

// Converte a string base64 num Buffer (binário nativo do Node.js)
const binaryData = Buffer.from(base64Data, 'base64');

return [{
  json: $json, // Mantém todos os dados originais
  // Cria o arquivo binário na estrutura interna do n8n
  binary: {
    // O nome da chave precisa ser EXATAMENTE 'imageBase64' para o Gemini achar
    imageBase64: {
      data: binaryData.toString('base64'),
      mimeType: 'image/jpeg', // Assumimos JPEG por padrão para envio
      fileName: 'imagem_paciente.jpg'
    }
  }
}];

// Verifica se a Silvia colocou a tag secreta de receita
const precisaEtiquetar = $json.text.includes('[ETIQUETA_RECEITA]');

// Limpa a tag da mensagem para o paciente não ver
const textoLimpo = $json.text.replace('[ETIQUETA_RECEITA]', '').trim();

return {
  json: {
    ...$json,
    text: textoLimpo,         // A mensagem limpa pronta para enviar
    addLabel: precisaEtiquetar // Um aviso "True" ou "False" para o n8n
  }
};
